// 把 links 数组拆成独立 items 供 MCP Client 逐条处理
const p = $('Extract Params').item.json;
const links = Array.isArray(p.links) ? p.links : [p.links].filter(Boolean);
if (links.length === 0) throw new Error('No links provided');
return links.map((url, i) => ({ json: { url, index: i + 1, total: links.length } }));

// 解析 MCP 返回, 提取热榜笔记核心数据
const rows = $input.all();
const notes = [];
for (const row of rows) {
  const sc = row.json.structuredContent || {};
  const data = sc.data || {};
  if (!data['作品标题']) continue;
  notes.push({
    title: data['作品标题'] || '',
    desc: (data['作品描述'] || '').slice(0, 600),
    tags: (data['作品标签'] || '').split(/\s+/).filter(Boolean).slice(0, 10),
    likes: data['点赞数量'] || '',
    collects: data['收藏数量'] || '',
    comments: data['评论数量'] || '',
    author: data['作者昵称'] || '',
    type: data['作品类型'] || '',
    url: data['作品链接'] || ''
  });
}
const params = $('Extract Params').item.json;
return [{ json: { notes, num_images: params.num_images, tg_chat_id: params.tg_chat_id, tg_bot_token: params.tg_bot_token, drafts_root: params.drafts_root }}];

// 组装 hauhau 提示词: 热榜数据 + baoyu 爆款规则
const p = $input.first().json;
const notes = p.notes || [];
const samplesText = notes.map((n, i) => `热度样本${i+1}【${n.author}】${n.title}\n(赞${n.likes} 藏${n.collects} 评${n.comments})\n正文摘要: ${n.desc.slice(0, 300)}\n标签: ${n.tags.join(' ')}`).join('\n\n---\n\n');

const sysPrompt = `你是专业的小红书爆款文案师, 账号定位为家居装修干货号「宅有宅的道理」, 主打中古风装修内容。严格遵守: (1) 标题15字内, 带emoji, 有钩子, 有代入感, 格式参考「X式中古 | 元素1+元素2+元素3, 情感句」; (2) 正文250-600字, 短句多段, emoji点缀, 有场景感, 干货密度高, 可直接照做; (3) 结尾3-5个疑问句或CTA, 但禁止诱导互动(禁「评论区扣XX领资料」「私信领包」等); (4) 8-10个中文tag; (5) ${p.num_images}张配图的英文prompt, 每张60词内, 描述具体场景+光线+构图, 覆盖不同角度/景别.

**严格禁止**: 正文body里不允许出现以 # 开头的行或裸tag, tag只在返回JSON的tags数组里, 不许在body里重复; 不许把tags再以 ## 双井号形式重复输出.

严格返回JSON: {"title":"...", "body":"...", "tags":["tag1",...共8-10个], "image_prompts":["en1",...共${p.num_images}个]}`;

const userPrompt = `下面是小红书热榜/高赞笔记的真实数据, 请提炼这些内容的爆款共性(主题方向、情绪钩子、干货结构), 并创作一篇属于「宅有宅的道理」账号的全新装修干货笔记(可迭代升级选题, 不要照抄原文):

${samplesText}`;

const chatBody = {
  model: 'Qwen3.6-35B-Hauhau',
  temperature: 0.85,
  max_tokens: 9000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sysPrompt },
    { role: 'user', content: userPrompt }
  ]
};
return [{ json: { chat_body: chatBody, num_images: p.num_images, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token, drafts_root: p.drafts_root, hot_count: (notes||[]).length }}];

const fs = require('fs');
const raw = $input.first().json.choices[0].message.content;
let data = {};
for (let i = 0; i < 3; i++) {
  try { data = JSON.parse(raw); break; } catch (e) { const m = raw.match(/{[\s\S]*}/); if (m) raw = m[0]; else throw new Error('Invalid JSON from hauhau: ' + raw.slice(0,200)); }
}
const prev = $('Build Hauhau Prompt').item.json;
let body = (data.body || '').split('\n').filter(line => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(line)).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const tagsClean = [...new Set((data.tags || []).map(t => t.replace(/^#+/, '').trim()).filter(Boolean))];
const ts = new Date().toISOString().slice(0,19).replace(/[-:T]/g,'');
const draftDir = `${prev.drafts_root}/${ts}`;
fs.mkdirSync(draftDir, { recursive: true });
const mdPath = `${draftDir}/note.md`;
const md = `# ${data.title}\n\n${body}\n\n${tagsClean.map(t=>'#'+t).join(' ')}\n\n---\n_基于 ${prev.hot_count} 篇热榜笔记提炼生成_\n`;
fs.writeFileSync(mdPath, md);
const prompts = data.image_prompts || [];
const n = Math.min(prev.num_images, prompts.length);
const result = [];
for (let i = 0; i < n; i++) {
  result.push({ json: { prompt: prompts[i], index: i + 1, total: n, draft_dir: draftDir, md_path: mdPath, title: data.title, body: body, tags: tagsClean, hot_count: prev.hot_count, tg_chat_id: prev.tg_chat_id, tg_bot_token: prev.tg_bot_token }});
}
return result;

const item = $input.first().json;
const seed = Math.floor(Math.random() * 1000000000);
const workflow = {
  '1': {class_type:'UNETLoader', inputs:{unet_name:'qwen_image_fp8_e4m3fn.safetensors', weight_dtype:'default'}},
  '2': {class_type:'CLIPLoader', inputs:{clip_name:'qwen_2.5_vl_7b_fp8_scaled.safetensors', type:'qwen_image'}},
  '3': {class_type:'VAELoader', inputs:{vae_name:'qwen_image_vae.safetensors'}},
  '4': {class_type:'ModelSamplingAuraFlow', inputs:{model:['1',0], shift:3.1}},
  '5': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:item.prompt}},
  '6': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:''}},
  '7': {class_type:'EmptySD3LatentImage', inputs:{width:1024, height:1024, batch_size:1}},
  '8': {class_type:'KSampler', inputs:{model:['4',0], positive:['5',0], negative:['6',0], latent_image:['7',0], seed, steps:20, cfg:2.5, sampler_name:'euler', scheduler:'simple', denoise:1.0}},
  '9': {class_type:'VAEDecode', inputs:{samples:['8',0], vae:['3',0]}},
  '10': {class_type:'SaveImage', inputs:{images:['9',0], filename_prefix:`n8n-xhs-${item.index}`}}
};
return [{ json: { comfy_body: { prompt: workflow, client_id: 'n8n' }, ...item }}];

const fs = require('fs');
const http = require('http');
const promptId = $input.first().json.prompt_id;
const prev = $('Build Comfy Workflow').item.json;
async function getJson(url) { return new Promise((res, rej) => http.get(url, r => { let d=''; r.on('data',c=>d+=c); r.on('end',()=>{try{res(JSON.parse(d))}catch(e){rej(e)}}); }).on('error', rej)); }
async function getBinary(url) { return new Promise((res, rej) => http.get(url, r => { const c=[]; r.on('data',b=>c.push(b)); r.on('end',()=>res(Buffer.concat(c))); }).on('error', rej)); }
const dl = Date.now() + 900000;
let result = null;
while (Date.now() < dl) {
  const d = await getJson(`http://127.0.0.1:8189/history/${promptId}`);
  if (d[promptId]) {
    const e = d[promptId], st = e.status || {};
    if (st.completed) {
      for (const nid in e.outputs || {}) {
        for (const img of (e.outputs[nid].images || [])) {
          const u = `http://127.0.0.1:8189/view?filename=${img.filename}&subfolder=${img.subfolder||''}&type=output`;
          const buf = await getBinary(u);
          const dest = `${prev.draft_dir}/img-${String(prev.index).padStart(2,'0')}-${img.filename}`;
          fs.writeFileSync(dest, buf);
          result = { saved: dest, filepath: dest };
          break;
        }
        if (result) break;
      }
      break;
    }
    if (st.status_str === 'error') { result = { error: 'workflow error' }; break; }
  }
  await new Promise(r => setTimeout(r, 3000));
}
if (!result) result = { error: 'timeout' };
return [{ json: { ...result, ...prev }}];

const fs = require('fs');
const dir = $('Keep First (dedup)').item.json.draft_dir;
const files = fs.readdirSync(dir).filter(f => f.startsWith('img-')).sort();
const prev = $('Parse + Save + Split').first().json;
const md = fs.readFileSync(`${dir}/note.md`, 'utf8');
return [{ json: { ...prev, draft_dir: dir, images: files } }];
